import re
import time
import requests

VT = "https://www.virustotal.com/api/v3"
HASH_RE = re.compile(r"[0-9a-f]{32}|[0-9a-f]{40}|[0-9a-f]{64}")

def lookup_hash(session, h, base=VT, max_tries=3):
    if not HASH_RE.fullmatch(h):
        raise ValueError(f"not an MD5, SHA-1 or SHA-256: {h!r}")
    for attempt in range(max_tries):
        r = session.get(f"{base}/files/{h}", timeout=(3.05, 10))
        if r.status_code == 404:
            return {"hash": h, "known": False}
        if r.status_code == 429:
            time.sleep(int(r.headers.get("Retry-After", "60")))
            continue
        r.raise_for_status()
        stats = r.json()["data"]["attributes"]["last_analysis_stats"]
        return {"hash": h, "known": True,
                "malicious": stats["malicious"]}
    raise RuntimeError(f"gave up on {h} after {max_tries} tries")

def enrich(hashes, api_key, base=VT, per_minute=4):
    session = requests.Session()
    session.headers["x-apikey"] = api_key
    cache = {}
    results = []
    for raw in hashes:
        h = raw.strip().lower()
        if h not in cache:
            cache[h] = lookup_hash(session, h, base)
            time.sleep(60 / per_minute)
        results.append(cache[h])
    return results

