import ipaddress
import subprocess

def safe_ping(target):
    ip = ipaddress.ip_address(target)          # ValueError if not an IP
    return subprocess.run(["ping", "-c", "1", str(ip)],
                          capture_output=True, text=True, timeout=10)

try:
    safe_ping("192.0.2.1; echo INJECTED")
except ValueError as e:
    print("rejected:", e)

