import pytest
from enrich import lookup_hash

class FakeResponse:
    def __init__(self, status, body=None, headers=None):
        self.status_code = status
        self.headers = headers or {}
        self._body = body
    def json(self):
        return self._body
    def raise_for_status(self):
        if self.status_code >= 400:
            raise RuntimeError(self.status_code)

class FakeSession:
    def __init__(self, responses):
        self.responses = list(responses)
        self.urls = []
    def get(self, url, timeout):
        self.urls.append(url)
        return self.responses.pop(0)

H = "5bef35496fcbdbe841c82f4d1ab8b7c2"

def test_404_means_unknown_not_clean():
    s = FakeSession([FakeResponse(404)])
    assert lookup_hash(s, H) == {"hash": H, "known": False}

def test_429_waits_then_retries(monkeypatch):
    monkeypatch.setattr("time.sleep", lambda seconds: None)
    body = {"data": {"attributes": {"last_analysis_stats": {"malicious": 7}}}}
    s = FakeSession([FakeResponse(429, headers={"Retry-After": "1"}),
                     FakeResponse(200, body)])
    assert lookup_hash(s, H)["malicious"] == 7
    assert len(s.urls) == 2

def test_rejects_non_hash_input():
    with pytest.raises(ValueError):
        lookup_hash(FakeSession([]), "../../users/me")
